import type { Generated, Insertable, Selectable, Updateable } from "kysely";

/** One change to a holding: "+3 of this share" or "−2 of that one". */
export interface PortfolioChangeTable {
  /** Generated by Postgres, or the UUID the client generated for the entry. */
  id: Generated<string>;
  /** The member whose holding changes. */
  userId: string;
  shareId: string;
  /** A decimal string, never zero: above zero for a purchase, below for a sale. */
  quantityDelta: string;
  /** When the change happened. Never in the future: the API checks it. */
  effectiveAt: Date;
  /** The member, or the admin editing on their behalf. Empty once that person is deleted. */
  createdBy: string | null;
  createdAt: Generated<Date>;
}

export type PortfolioChange = Selectable<PortfolioChangeTable>;
export type NewPortfolioChange = Insertable<PortfolioChangeTable>;
export type PortfolioChangeUpdate = Updateable<PortfolioChangeTable>;
